const members = $input.all();

const timezone = 'Africa/Lagos';

const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const [, todayMonth, todayDay] = today.split('-').map(Number);


// ================================
// DATE PARSER
// ================================
function parseBirthday(value) {
  if (!value) return null;

  const text = String(value).trim();

  // YYYY-MM-DD
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

  if (match) {
    return {
      month: Number(match[2]),
      day: Number(match[3]),
    };
  }

  // DD/MM/YYYY
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (match) {
    return {
      month: Number(match[2]),
      day: Number(match[1]),
    };
  }

  // DD-MM-YYYY
  match = text.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/);

  if (match) {
    return {
      month: Number(match[2]),
      day: Number(match[1]),
    };
  }

  return null;
}


// ================================
// EMAIL CLEANER
// ================================
function cleanEmail(value) {
  if (!value) return '';

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '')
    .replace(/@gmail\.con$/i, '@gmail.com')
    .replace(/@gmial\.com$/i, '@gmail.com')
    .replace(/@gamil\.com$/i, '@gmail.com');
}


// ================================
// FIND BIRTHDAYS
// ================================
return members
  .filter(item => {

    const m = item.json;

    // Gender
    const gender = String(m.Gender || '')
      .trim()
      .toLowerCase();

    if (gender !== 'male') {
      return false;
    }

    // DOB
    const dob = parseBirthday(m['Date of Birth']);

    if (!dob) {
      return false;
    }

    // Birthday today?
    if (
      dob.month !== todayMonth ||
      dob.day !== todayDay
    ) {
      return false;
    }

    // Don't send twice today
    const lastSent = String(
      m['Birthday Message Date'] || ''
    ).slice(0, 10);

    if (lastSent === today) {
      return false;
    }

    return true;
  })

  .map(item => {

    const m = item.json;

    return {
      json: {
        ...m,

        birthdayRunDate: today,

        birthdayName: m['Full Name'],

        birthdayEmail: cleanEmail(m.Email),

        birthdayWhatsApp: m.WhatsApp,

        birthdayDateNormalized: today,
      },

      pairedItem: item.pairedItem,
    };
  });
